import { isDateTimePartiallyOrWithinDomain } from './is-datetime-partially-or-within-domain.js';
import { isTimeframe } from '../../core/components/annotations-timeseries/functions/is-timeframe.js';
import { IndicatorData } from '../types/indicators.js';

export function filterIndicatorsOutOfBounds(
  indicators: IndicatorData[][],
  [domainStart, domainEnd]: number[],
): IndicatorData[][] {
  const filteredIndicators: IndicatorData[][] = [];

  indicators.forEach((track, index) => {
    filteredIndicators[index] = track.filter((indicator) => {
      const { start } = indicator;

      if (isTimeframe(indicator)) {
        const { end } = indicator;

        return isDateTimePartiallyOrWithinDomain(
          start,
          end,
          domainStart,
          domainEnd,
        );
      } else {
        return start.getTime() >= domainStart && start.getTime() <= domainEnd;
      }
    });
  });

  return filteredIndicators;
}
